 content.querySelector('.staff-role-right-all').onchange=e=>{[...selectedRoles].filter(role=>role.includes(rightSearch.value.trim())).forEach(role=>e.target.checked?rightChecked.add(role):rightChecked.delete(role));renderRoleLists();};
