  function visibleChannels(){const keyword=search.value.trim().toLowerCase();if(!keyword)return selectableChannels.map(node=>({...node,path:channelPath(node.name),matched:true}));const matches=selectableChannels.filter(node=>node.name.toLowerCase().includes(keyword)||channelPath(node.name).toLowerCase().includes(keyword));const needed=new Set(matches.map(node=>node.name));matches.forEach(node=>{let parent=node.parent;while(parent){needed.add(parent);parent=limitChannelTree.find(item=>item.name===parent)?.parent;}});return selectableChannels.filter(node=>needed.has(node.name)).map(node=>({...node,path:channelPath(node.name),matched:node.name.toLowerCase().includes(keyword)||channelPath(node.name).toLowerCase().includes(keyword)}));}
